// Consolida o resultado do SQL E-commerce no contrato único de dados do relatório.
// Ruptura e Demanda x Forecast: fontes ainda não disponíveis -> permanecem nulos (o HTML exibe "—").
const safe = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const cfg = $('Parâmetros').first().json;
const n = (v) => Number(v) || 0;
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().trim();

// Uma linha por MARCA, com todas as métricas (ver query do nó 'SQL - E-commerce').
const linhasSql = safe('SQL - E-commerce');

const zero = () => ({ ped_i: 0, pc_i: 0, rs_i: 0, ped_a: 0, pc_a: 0, rs_a: 0, ped_p: 0, pc_p: 0, rs_p: 0 });
const marcas = {};
const lookup = {};                                   // marca normalizada -> nome de exibição
cfg.marcasPrincipais.forEach(m => { marcas[m] = zero(); lookup[norm(m)] = m; });
marcas['Demais marcas'] = zero();
const bucket = (m) => lookup[norm(m)] || 'Demais marcas';

let backlog7d = { ped: 0, pc: 0, rs: 0 };
let lt = { soma: 0, qtd: 0, dentro: 0 };

linhasSql.forEach(r => {
  const b = marcas[bucket(r.MARCA ?? r.marca)];
  b.ped_i += n(r.ped_integrado); b.pc_i += n(r.pc_integrado); b.rs_i += n(r.rs_integrado);
  b.ped_a += n(r.ped_atendido);  b.pc_a += n(r.pc_atendido);  b.rs_a += n(r.rs_atendido);
  b.ped_p += n(r.ped_pendente);  b.pc_p += n(r.pc_pendente);  b.rs_p += n(r.rs_pendente);
  backlog7d.ped += n(r.ped_backlog_7d); backlog7d.pc += n(r.pc_backlog_7d); backlog7d.rs += n(r.rs_backlog_7d);
  lt.soma += n(r.soma_lead_time_h); lt.qtd += n(r.qtd_expedidos); lt.dentro += n(r.qtd_dentro_meta_lt);
});

const total = zero();
Object.values(marcas).forEach(m => Object.keys(total).forEach(k => total[k] += m[k]));

const kpis = {
  leadTimeH: lt.qtd > 0 ? lt.soma / lt.qtd : null,                 // média venda -> expedição (expedidos em D-1)
  slaPct: lt.qtd > 0 ? (lt.dentro / lt.qtd) * 100 : null,          // % expedidos em D-1 dentro da meta de lead time
  backlogAcimaSlaPed: backlog7d.ped,                               // backlog dos últimos 7 dias (pedidos)
  backlog7d,
  rupturaPct: null,                                                // fonte pendente
  demandaVsForecastPct: null                                       // fonte pendente
};

return [{ json: { cfg, marcas, total, kpis, geradoEm: new Date().toISOString() } }];

// Renderiza o template "DAILY LOGISTICS | ONE PAGE" a partir do contrato de dados.
const { cfg, marcas, total, kpis } = $input.first().json;
const hhmm = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' });

const isN = (v) => v === null || v === undefined || isNaN(v);
const num = (v) => isN(v) ? '—' : Number(v).toLocaleString('pt-BR', { maximumFractionDigits: 0 });
const dec = (v, c = 1) => isN(v) ? '—' : Number(v).toLocaleString('pt-BR', { minimumFractionDigits: c, maximumFractionDigits: c });
const mil = (v) => isN(v) ? '—' : (v >= 1000 ? dec(v / 1000, 1) + ' mil' : num(v));
const brl = (v) => isN(v) ? '—' : 'R$ ' + (v >= 1e6 ? dec(v / 1e6, 2) + ' mi' : num(v));
const tri = (p, c, r) => `${num(p)} ped. / ${num(c)} pç. / ${brl(r)}`;
const sub = (p, c, r) => `${num(p)} pedidos • ${num(c)} peças • ${brl(r)}`;
const withUnit = (v, fmt, unit) => isN(v) ? '—' : fmt(v) + unit;

const css = `
body{font-family:Segoe UI,Arial,sans-serif;color:#1a1a1a;margin:0;background:#fff}
.page{max-width:720px;margin:0 auto;padding:24px}
h1{font-size:16px;margin:0}.meta{font-size:11px;color:#666;margin:2px 0 18px}
.kpis{display:grid;grid-template-columns:1fr 1fr;gap:16px 40px;margin-bottom:24px}
.kpi .l{font-size:12px;color:#555}.kpi .v{font-size:24px;font-weight:700;margin:2px 0}.kpi .s{font-size:10px;color:#666}
h2{font-size:13px;margin:22px 0 4px;border-bottom:1px solid #ddd;padding-bottom:4px}
table{width:100%;border-collapse:collapse;font-size:11px}
th{text-align:left;padding:6px 4px;border-bottom:2px solid #1a1a1a}
td{padding:7px 4px;border-bottom:1px solid #e5e5e5}
tr.total td{font-weight:700;border-top:2px solid #1a1a1a}
.cards{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.card{border:1px solid #ccc;border-radius:4px;padding:10px 12px}
.card .l{font-size:11px;color:#555}.card .v{font-size:20px;font-weight:700;margin:2px 0}.card .s{font-size:10px;color:#777}
`;

const linhas = Object.entries(marcas).map(([m, v]) =>
  `<tr><td>${m}</td><td>${tri(v.ped_i, v.pc_i, v.rs_i)}</td><td>${tri(v.ped_a, v.pc_a, v.rs_a)}</td><td>${tri(v.ped_p, v.pc_p, v.rs_p)}</td></tr>`
).join('');

const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><style>${css}</style></head><body><div class="page">
<h1>DAILY LOGISTICS | ONE PAGE</h1>
<div class="meta">${cfg.grupo} • Data-base: D-1 (${cfg.dataBaseBR}) • Atualizado às ${hhmm}</div>

<div class="kpis">
  <div class="kpi"><div class="l">Demanda integrada</div><div class="v">${mil(total.ped_i)}</div><div class="s">${sub(total.ped_i, total.pc_i, total.rs_i)}</div></div>
  <div class="kpi"><div class="l">Volume atendido</div><div class="v">${mil(total.ped_a)}</div><div class="s">${sub(total.ped_a, total.pc_a, total.rs_a)}</div></div>
  <div class="kpi"><div class="l">Backlog pendente</div><div class="v">${mil(total.ped_p)}</div><div class="s">${sub(total.ped_p, total.pc_p, total.rs_p)}</div></div>
  <div class="kpi"><div class="l">Cumprimento do SLA</div><div class="v">${withUnit(kpis.slaPct, dec, '%')}</div><div class="s">Meta: ${cfg.slaMetaPct}% • expedidos em até ${cfg.leadTimeMetaH} h</div></div>
</div>

<h2>1. DEMANDA E ATENDIMENTO POR MARCA</h2>
<table><thead><tr><th>Marca</th><th>Integrado</th><th>Atendido</th><th>Pendente</th></tr></thead><tbody>
${linhas}
<tr class="total"><td>TOTAL GRUPO</td><td>${tri(total.ped_i, total.pc_i, total.rs_i)}</td><td>${tri(total.ped_a, total.pc_a, total.rs_a)}</td><td>${tri(total.ped_p, total.pc_p, total.rs_p)}</td></tr>
</tbody></table>

<h2>2. NÍVEL DE SERVIÇO E RISCOS</h2>
<div class="cards">
  <div class="card"><div class="l">Lead Time médio</div><div class="v">${withUnit(kpis.leadTimeH, (x) => dec(x, 1), ' h')}</div><div class="s">Meta: ${cfg.leadTimeMetaH} h</div></div>
  <div class="card"><div class="l">Ruptura</div><div class="v">${withUnit(kpis.rupturaPct, (x) => dec(x, 2), '%')}</div><div class="s">Meta: ${dec(cfg.rupturaMetaPct, 2)}%${isN(kpis.rupturaPct) ? ' • fonte pendente' : ''}</div></div>
  <div class="card"><div class="l">Backlog acima do SLA</div><div class="v">${withUnit(kpis.backlogAcimaSlaPed, num, ' pedidos')}</div><div class="s">Backlog dos últimos 7 dias</div></div>
  <div class="card"><div class="l">Demanda x Forecast</div><div class="v">${isN(kpis.demandaVsForecastPct) ? '—' : (kpis.demandaVsForecastPct >= 0 ? '+' : '') + dec(kpis.demandaVsForecastPct) + '%'}</div>${isN(kpis.demandaVsForecastPct) ? '<div class="s">Fonte pendente</div>' : ''}</div>
</div>
</div></body></html>`;

return [{ json: { html, assunto: `Daily Logistics | ${cfg.grupo} | ${cfg.dataBaseBR}`, dataBase: cfg.dataBase } }];
